3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
9	import org.springframework.web.bind.annotation.RequestBody;
10	
11	/**
12	 * First step of {@code POST /api/owners}. Rejects a create request that is missing or blank in any
13	 * required field, so an invalid body is a 400 whose {@code errors} array names each offending field.
14	 * Runs before {@link BuildOwner}, which then reads the published body via {@code @Val}.
15	 *
16	 * <p>The {@code address} is normalized in place first (see {@link AddressNormalizer}) so it is stored
17	 * and returned in normalized form, and so the required-field check rejects an address that is blank
18	 * after normalization (for example one made only of whitespace).
19	 */
20	public class ValidateOwnerFields {
21	
22	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
23	            throws MissingOwnerFieldsException {
24	        if (request.getAddress() != null) {
25	            request.setAddress(AddressNormalizer.normalize(request.getAddress()));
26	        }
27	        List<String> errors = new ArrayList<>();
28	        require(errors, "firstName", request.getFirstName());
29	        require(errors, "lastName", request.getLastName());
30	        require(errors, "address", request.getAddress());
31	        require(errors, "city", request.getCity());
32	        require(errors, "telephone", request.getTelephone());
33	        if (!errors.isEmpty()) {
34	            throw new MissingOwnerFieldsException(errors);
35	        }
36	        validated.set(request);
37	    }
38	
39	    private static void require(List<String> errors, String field, String value) {
40	        if (value == null || value.isBlank()) {
41	            errors.add(field);
42	        }
43	    }
44	}
