3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	
6	import net.officefloor.plugin.variable.Out;
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	
10	/**
11	 * Step of {@code POST /api/owners} that resolves the EFFECTIVE registration date and publishes it
12	 * for the later steps.
13	 *
14	 * <p>The effective date is the one supplied in the request body, or the server's current date when
15	 * the request omits one. Because a registration must fall on a business day, a date that lands on a
16	 * Saturday or Sunday is rolled forward to the next Monday — this applies whether the date was
17	 * supplied or defaulted.
18	 *
19	 * <p>Publishing the adjusted date once here keeps every value derived from it consistent: the daily
20	 * create-limit ({@link EnsureDailyLimit}) counts owners per this adjusted business day, the owner is
21	 * stored with it ({@link DefaultOwnerRegistrationDate}) and the membership number's year segment is
22	 * therefore taken from the adjusted date.
23	 */
24	public class ResolveRegistrationDate {
25	
26	    public void service(@Val OwnerFieldsDto request, Out<LocalDate> registrationDate) {
27	        LocalDate effective = request.getRegistrationDate() != null
28	                ? request.getRegistrationDate() : LocalDate.now();
29	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY
30	                || effective.getDayOfWeek() == DayOfWeek.SUNDAY) {
31	            effective = effective.plusDays(1);
32	        }
33	        registrationDate.set(effective);
34	    }
35	}
