3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
8	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
9	
10	/**
11	 * Rejects a create-owner request whose E.164 telephone is already used by an existing owner, responding
12	 * 409 via {@link DuplicateTelephoneException}. Runs after {@link NormalizeOwnerTelephone} (which
13	 * guarantees the request telephone is the E.164 form) and before {@link BuildOwner}, comparing against
14	 * every stored owner's telephone normalized to E.164 the same way. Existing telephones that cannot form
15	 * a valid E.164 number are skipped rather than blocking the request.
16	 */
17	public class EnsureUniqueTelephone {
18	
19	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
20	            throws DuplicateTelephoneException {
21	        String telephone = request.getTelephone();
22	        for (Owner existing : ownerRepository.findAll()) {
23	            String existingE164;
24	            try {
25	                existingE164 = E164Telephone.normalize(existing.getTelephone());
26	            }
27	            catch (InvalidTelephoneException ex) {
28	                continue;
29	            }
30	            if (existingE164.equals(telephone)) {
31	                throw new DuplicateTelephoneException(telephone);
32	            }
33	        }
34	    }
35	}
