1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
8	
9	/**
10	 * Rejects a create-owner request whose last name and address already belong to an existing owner,
11	 * responding 409 via {@link DuplicateHouseholdException}. Last name is compared case-insensitively
12	 * after trimming and collapsing every run of whitespace to a single space; the address is compared
13	 * using its canonical normalized form (see {@link AddressNormalizer}) so, for example, {@code 12 main
14	 * st} and {@code 12  Main  Street} match. A request that sets {@code sharesHousehold} true bypasses
15	 * the check and is allowed through.
16	 */
17	public class EnsureUniqueHousehold {
18	
19	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
20	            throws DuplicateHouseholdException {
21	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
22	            return;
23	        }
24	        String lastName = normalize(request.getLastName());
25	        String address = AddressNormalizer.normalize(request.getAddress());
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (normalize(existing.getLastName()).equals(lastName)
28	                    && AddressNormalizer.normalize(existing.getAddress()).equals(address)) {
29	                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
30	            }
31	        }
32	    }
33	
34	    private static String normalize(String value) {
35	        if (value == null) {
36	            return "";
37	        }
38	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
39	    }
40	}
