10	/**
11	 * Rejects a create-owner request once 100 or more owners have already been registered on the
12	 * request's adjusted business day (the effective {@code registrationDate} resolved by
13	 * {@link ResolveRegistrationDate}), responding 429 via {@link DailyLimitReachedException}. Runs
14	 * before {@link SaveOwner}, so the count excludes the owner being created.
15	 */
16	public class EnsureDailyLimit {
17	
18	    private static final int DAILY_LIMIT = 100;
19	
20	    public void service(@Val LocalDate registrationDate, OwnerRepository ownerRepository)
21	            throws DailyLimitReachedException {
22	        int count = 0;
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (registrationDate.equals(existing.getRegistrationDate())) {
25	                count++;
26	            }
27	        }
28	        if (count >= DAILY_LIMIT) {
29	            throw new DailyLimitReachedException(count);
30	        }
31	    }
32	}
