2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	
12	/**
13	 * Step of {@code POST /api/owners} that assigns a shared {@code householdId} when the request opts
14	 * into an existing household via {@code sharesHousehold}.
15	 *
16	 * <p>When {@code sharesHousehold} is true and an existing owner already shares the same last name
17	 * and address (last name compared case-insensitively after trimming and collapsing whitespace, and
18	 * address by its canonical normalized form, matching {@link EnsureUniqueHousehold}), a stable
19	 * identifier derived from that normalized last name and address is assigned to the new owner and
20	 * back-filled onto every matching existing owner. Because
21	 * the identifier is derived deterministically from the household key, all owners of a household share
22	 * the same value regardless of creation order. Runs after {@link BuildOwner}, so it works on the
23	 * built entity, and before {@link SaveOwner}.
24	 */
25	public class AssignHousehold {
26	
27	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
28	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
29	            return;
30	        }
31	        String lastName = normalize(request.getLastName());
32	        String address = AddressNormalizer.normalize(request.getAddress());
33	        String householdId = null;
34	        for (Owner existing : ownerRepository.findAll()) {
35	            if (normalize(existing.getLastName()).equals(lastName)
36	                    && AddressNormalizer.normalize(existing.getAddress()).equals(address)) {
37	                if (householdId == null) {
38	                    householdId = householdId(lastName, address);
39	                }
40	                if (!householdId.equals(existing.getHouseholdId())) {
41	                    existing.setHouseholdId(householdId);
42	                    ownerRepository.save(existing);
43	                }
44	            }
45	        }
46	        if (householdId != null) {
47	            owner.setHouseholdId(householdId);
48	        }
49	    }
50	
51	    private static String householdId(String lastName, String address) {
52	        String key = lastName + "|" + address;
53	        try {
54	            byte[] digest = MessageDigest.getInstance("SHA-256")
55	                    .digest(key.getBytes(StandardCharsets.UTF_8));
56	            StringBuilder sb = new StringBuilder("H-");
57	            for (int i = 0; i < 6; i++) {
58	                sb.append(String.format("%02X", digest[i]));
59	            }
60	            return sb.toString();
61	        }
62	        catch (NoSuchAlgorithmException e) {
63	            throw new IllegalStateException("SHA-256 not available", e);
64	        }
65	    }
66	
67	    private static String normalize(String value) {
68	        if (value == null) {
69	            return "";
70	        }
71	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
72	    }
73	}
