1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Step of {@code POST /api/owners} that assigns the owner's {@code customerCode}.
9	 *
10	 * <p>The code is formatted {@code '<CITY3>-<LAST3>-<NNNN>'}, where CITY3 is the upper-cased
11	 * first three letters of the owner's city, LAST3 the upper-cased first three letters of the
12	 * owner's last name and NNNN a per-city 4-digit zero-padded sequence equal to one more than
13	 * the number of owners already in that city (e.g. {@code 'LON-SMI-0007'}). Runs before
14	 * {@link SaveOwner}, so the count excludes the owner being created.
15	 */
16	public class AssignCustomerCode {
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
19	        String city = owner.getCity();
20	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
21	        String lastName = owner.getLastName();
22	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
23	        int sequence = (int) ownerRepository.findAll().stream()
24	                .filter(o -> city.equalsIgnoreCase(o.getCity()))
25	                .count() + 1;
26	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
27	    }
28	}
