3	/**
4	 * Canonical normalization for an owner's {@code address}. Whitespace is trimmed and every run of
5	 * whitespace collapsed to a single space, the text is upper-cased, and common abbreviations are
6	 * expanded on a whole-word basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
7	 * The transform is idempotent, so normalizing an already-normalized address returns it unchanged.
8	 *
9	 * <p>Applied whenever an owner is created (see {@link ValidateOwnerFields}) so the stored and returned
10	 * {@code address} is the normalized string, and reused wherever addresses are compared
11	 * ({@link EnsureUniqueHousehold}, {@link AssignHousehold}) so those comparisons see the same form.
12	 */
13	final class AddressNormalizer {
14	
15	    private AddressNormalizer() {
16	    }
17	
18	    static String normalize(String address) {
19	        if (address == null) {
20	            return "";
21	        }
22	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
23	        if (collapsed.isEmpty()) {
24	            return "";
25	        }
26	        String[] tokens = collapsed.split(" ");
27	        StringBuilder sb = new StringBuilder(collapsed.length());
28	        for (int i = 0; i < tokens.length; i++) {
29	            if (i > 0) {
30	                sb.append(' ');
31	            }
32	            sb.append(expand(tokens[i]));
33	        }
34	        return sb.toString();
35	    }
36	
37	    private static String expand(String token) {
38	        switch (token) {
39	            case "ST":
40	                return "STREET";
41	            case "RD":
42	                return "ROAD";
43	            case "AVE":
44	                return "AVENUE";
45	            default:
46	                return token;
47	        }
48	    }
