5	/**
6	 * Converts a supplied telephone into E.164 form. Spaces, dashes and brackets are stripped; a leading
7	 * '+' with its country code is kept when present, otherwise country code '+61' is assumed and a single
8	 * leading '0' is dropped from the national digits. The result must carry 8 to 15 digits after the '+',
9	 * otherwise it cannot form a valid E.164 number and an {@link InvalidTelephoneException} (400) is thrown.
10	 */
11	final class E164Telephone {
12	
13	    private E164Telephone() {
14	    }
15	
16	    static String normalize(String telephone) throws InvalidTelephoneException {
17	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\[\\]-]", "");
18	        boolean hasPlus = cleaned.startsWith("+");
19	        String rest = hasPlus ? cleaned.substring(1) : cleaned;
20	        if (rest.isEmpty() || !rest.chars().allMatch(Character::isDigit)) {
21	            throw new InvalidTelephoneException(telephone);
22	        }
23	        String digits;
24	        if (hasPlus) {
25	            digits = rest;
26	        }
27	        else {
28	            String national = rest.startsWith("0") ? rest.substring(1) : rest;
29	            digits = "61" + national;
30	        }
31	        if (digits.length() < 8 || digits.length() > 15) {
32	            throw new InvalidTelephoneException(telephone);
33	        }
34	        return "+" + digits;
35	    }
36	}
